/* =========================================
   RESET Y VARIABLES GLOBALES
   ========================================= */
*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* Colores principales */
    --color-bg-dark: #1A1206;
    --color-bg-sidebar: #241A0B;
    --color-bg-card: #2A1E10;
    --color-border: #3b3222;
    --color-border-light: #4a3d2a;
    --color-primary: #F2A900;
    --color-primary-hover: #FFBF2E;
    --color-text-white: #F5F5F5;
    --color-text-gray: #9c9993;
    --color-text-dark: #1A1206;
    --color-alert-green: #4CAF50;

    /* Tipografía */
    --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

    /* Sidebar */
    --sidebar-width: clamp(240px, 20%, 300px);

    /* Bordes */
    --radius-sm: 8px;
    --radius-md: 12px;
    --radius-lg: 16px;
    --radius-pill: 50px;
}

body {
    font-family: var(--font-main);
    background-color: var(--color-bg-dark);
    color: var(--color-text-white);
    overflow-x: hidden;
}

/* =========================================
   APP SHELL (contenedor general)
   ========================================= */
.app-shell {
    display: flex;
    min-height: 100vh;
}

/* =========================================
   SIDEBAR
   ========================================= */
.sidebar {
    position: fixed;
    top: 0;
    left: 0;
    width: var(--sidebar-width);
    height: 100vh;
    background-color: var(--color-bg-sidebar);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: clamp(18px, 1.25vw, 30px);
    z-index: 100;
}

/* =========================================
   LOGO
   ========================================= */
.sidebar .logo {
    display: flex;
    flex-direction: row;
    align-items: center;
    margin-bottom: clamp(18px, 1.25vw, 30px);
    gap: clamp(7px, 0.5vw, 12px);
}

.sidebar .logo .hexagon {
    width: clamp(58px, 4.0vw, 96px);
    min-width: clamp(58px, 4.0vw, 96px);
    height: clamp(56px, 3.94vw, 95px);
    background-color: var(--color-primary);
    clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
    display: flex;
    justify-content: center;
    align-items: center;
}

.sidebar .logo img {
    width: clamp(49px, 3.43vw, 83px);
    height: auto;
    object-fit: contain;
}

.sidebar .logo-text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    transform: translateY(-4px);
}

.sidebar .logo-text h1 {
    font-family: var(--font-main);
    color: var(--color-primary);
    font-size: clamp(18px, 1.25vw, 30px);
    font-weight: bold;
    margin: 0;
    line-height: 1;
}

.sidebar .logo-text p {
    font-family: var(--font-main);
    color: var(--color-text-gray);
    font-size: clamp(12px, 0.88vw, 22px);
    margin: 0;
    margin-top: 2px;
    white-space: nowrap;
}

/* =========================================
   MENÚ DE NAVEGACIÓN
   ========================================= */
.sidebar .menu {
    width: 100%;
}

.sidebar .menu ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar .menu ul li {
    width: 100%;
}

.sidebar .menu ul li a {
    font-family: var(--font-main);
    font-size: clamp(12px, 0.88vw, 22px);
    display: flex;
    align-items: center;
    gap: clamp(13px, 0.94vw, 23px);
    width: auto;
    padding: clamp(10px, 0.62vw, 14px) clamp(18px, 1.25vw, 30px);
    color: var(--color-text-white);
    text-decoration: none;
    transition: all 0.2s ease;
}

.sidebar .menu ul li a .menu-icon {
    width: clamp(18px, 1.25vw, 30px);
    height: clamp(18px, 1.25vw, 30px);
    filter: brightness(0) invert(1);
    transition: filter 0.2s ease;
}

/* Estado hover del menú */
.sidebar .menu ul li a:hover {
    background-color: var(--color-primary);
    color: var(--color-text-dark);
    border: none;
    outline: none;
    border-radius: var(--radius-md);
}

.sidebar .menu ul li a:hover .menu-icon {
    filter: brightness(0);
}

/* Estado activo del menú (página actual) */
.sidebar .menu ul li a.active {
    background-color: var(--color-primary);
    color: var(--color-text-dark);
    border-radius: var(--radius-md);
    font-weight: 600;
}

.sidebar .menu ul li a.active .menu-icon {
    filter: brightness(0);
}

/* =========================================
   PERFIL DE USUARIO EN SIDEBAR
   ========================================= */
.sidebar .user-profile {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: clamp(13px, 0.94vw, 23px);
    padding: clamp(18px, 1.25vw, 30px);
    margin-top: auto;
    margin-bottom: clamp(18px, 1.25vw, 30px);
    width: 100%;
    box-sizing: border-box;
}

.sidebar .user-avatar-indicator {
    position: relative;
    flex-shrink: 0;
}

.sidebar .user-profile .avatar-initials {
    width: clamp(41px, 2.81vw, 67px);
    height: clamp(41px, 2.81vw, 67px);
    border-radius: 50%;
    background-color: var(--color-primary);
    color: var(--color-text-dark);
    font-family: var(--font-main);
    font-size: clamp(16px, 1.1vw, 24px);
    font-weight: 700;
    display: flex;
    justify-content: center;
    align-items: center;
    letter-spacing: 1px;
}

.sidebar .status-dot {
    position: absolute;
    bottom: 2px;
    left: 0;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 2px solid var(--color-bg-sidebar);
}

.sidebar .status-dot.online {
    background-color: var(--color-alert-green);
}

.sidebar .user-profile .profile-text {
    display: flex;
    flex-direction: column;
}

.sidebar .user-profile h2 {
    font-family: var(--font-main);
    color: var(--color-text-white);
    font-size: clamp(14px, 1.0vw, 24px);
    font-weight: bold;
    margin: 0;
    line-height: 1.2;
}

.sidebar .user-profile p {
    font-family: var(--font-main);
    color: var(--color-text-gray);
    font-size: clamp(12px, 0.82vw, 19px);
    margin: 0;
}

/* =========================================
   CONTENIDO PRINCIPAL
   ========================================= */
.main-content {
    margin-left: var(--sidebar-width);
    width: calc(100% - var(--sidebar-width));
    min-height: 100vh;
    background-color: var(--color-bg-dark);
    padding: clamp(18px, 1.5vw, 30px);
    display: flex;
    flex-direction: column;
    gap: clamp(16px, 1.2vw, 24px);
    overflow-y: auto;
}

/* =========================================
   HEADER
   ========================================= */
.main-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
}

.header-left h1 {
    font-family: var(--font-main);
    font-size: clamp(20px, 1.6vw, 32px);
    font-weight: 700;
    color: var(--color-text-white);
    margin: 0;
}

.header-left p {
    font-family: var(--font-main);
    font-size: clamp(12px, 0.85vw, 16px);
    color: var(--color-text-gray);
    margin: 0;
    margin-top: 2px;
}

.header-right {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-left: auto;
}

/* Botón Mi Cuenta */
.user-account {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 6px 18px 6px 6px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background-color: transparent;
    cursor: pointer;
    transition: all 0.25s ease;
}

.user-account:hover {
    border-color: var(--color-primary);
}

.user-account-dot {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background-color: var(--color-primary);
    display: inline-block;
    flex-shrink: 0;
}

.user-account span:last-child {
    color: var(--color-text-white);
    font-family: var(--font-main);
    font-weight: 500;
    font-size: clamp(12px, 0.78vw, 16px);
    white-space: nowrap;
}

/* =========================================
   RESPONSIVE
   ========================================= */
@media (max-width: 768px) {
    .sidebar {
        display: none;
    }
    .main-content {
        margin-left: 0;
        width: 100%;
    }
    .main-header {
        flex-direction: column;
        align-items: flex-start;
    }
}

