args.ReplacementContent:
/* =========================================
   BARRA DE NAVEGACIÓN MÓVIL (oculta en desktop)
   ========================================= */
.mobile-nav {
    display: none;
}

/* =========================================
   RESPONSIVE - TABLET (≤ 1100px)
   ========================================= */
@media (max-width: 1100px) {
    .stats-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .charts-section {
        grid-template-columns: 1fr;
    }
}

/* =========================================
   RESPONSIVE - MÓVIL (≤ 768px)
   ========================================= */
@media (max-width: 768px) {
    /* Ocultar sidebar en móvil */
    .sidebar {
        display: none;
    }

    /* Contenido principal ocupa toda la pantalla */
    .main-content {
        margin-left: 0;
        width: 100%;
        padding: 16px;
        padding-bottom: 90px; /* Espacio para la barra de navegación inferior */
        gap: 16px;
    }

    /* Header móvil */
    .main-header {
        flex-direction: row;
        align-items: center;
    }

    .header-left h1 {
        font-size: 22px;
    }

    .header-left p {
        font-size: 12px;
    }

    /* Ocultar botón "Mi Cuenta" en móvil (se accede desde Menú) */
    .user-account {
        display: none;
    }

    /* Renombrar "Ver historial" a "Filtrar" visualmente con CSS no es posible,
       pero ajustamos el estilo del botón para móvil */
    .btn-historial {
        padding: 8px 18px;
        font-size: 13px;
    }

    /* Stats en 2x2 */
    .stats-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }

    .stat-card {
        padding: 14px 16px;
    }

    .stat-label {
        font-size: 10px;
    }

    .stat-value {
        font-size: 24px;
    }

    /* Gráficas apiladas verticalmente */
    .charts-section {
        grid-template-columns: 1fr;
        gap: 12px;
    }

    .chart-card {
        padding: 16px;
    }

    .chart-body {
        min-height: 160px;
        max-height: 200px;
    }

    /* Apiarios: tarjetas verticales full-width */
    .apiarios-section {
        padding: 16px;
        background-color: transparent;
        border: none;
    }

    .apiarios-title {
        font-size: 18px;
        margin-bottom: 12px;
    }

    .apiarios-scroll-container {
        flex-direction: column;
        overflow-x: visible;
        overflow-y: visible;
        gap: 10px;
        padding-bottom: 0;
    }

    /* Ocultar scrollbar en móvil (ya no hace falta) */
    .apiarios-scroll-container::-webkit-scrollbar {
        display: none;
    }

    .apiario-card {
        min-width: 100%;
        max-width: 100%;
        background-color: var(--color-bg-card);
        border: 1px solid var(--color-border);
        border-radius: var(--radius-md);
        padding: 16px;
        display: flex;
        align-items: center;
        gap: 12px;
        position: relative;
    }

    .apiario-card:hover {
        transform: none;
    }

    /* Flecha chevron a la derecha en móvil */
    .apiario-card::after {
        content: "›";
        position: absolute;
        right: 16px;
        top: 50%;
        transform: translateY(-50%);
        font-size: 24px;
        color: var(--color-text-gray);
        font-weight: 300;
    }

    .apiario-info .apiario-estado {
        display: none; /* Ocultar texto de estado en móvil, el dot ya lo indica */
    }

    .apiario-info .apiario-location {
        font-size: 12px;
    }

    .apiario-info h3 {
        font-size: 15px;
    }

    /* ===== BARRA DE NAVEGACIÓN INFERIOR ===== */
    .mobile-nav {
        display: flex;
        position: fixed;
        bottom: 0;
        left: 0;
        right: 0;
        height: 70px;
        background-color: var(--color-bg-sidebar);
        border-top: 1px solid var(--color-border);
        justify-content: space-around;
        align-items: center;
        padding: 0 8px;
        padding-bottom: env(safe-area-inset-bottom, 0); /* Para iPhones con notch */
        z-index: 200;
    }

    .mobile-nav-item {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 4px;
        text-decoration: none;
        padding: 8px 12px;
        border-radius: 10px;
        transition: all 0.2s ease;
        -webkit-tap-highlight-color: transparent;
    }

    .mobile-nav-item span {
        font-family: var(--font-main);
        font-size: 10px;
        font-weight: 500;
        color: var(--color-text-gray);
        transition: color 0.2s ease;
    }

    .mobile-nav-icon {
        width: 22px;
        height: 22px;
        filter: brightness(0) invert(0.6);
        transition: filter 0.2s ease;
    }

    /* SVG inline (el icono de Menú) */
    svg.mobile-nav-icon {
        filter: none;
        color: var(--color-text-gray);
    }

    /* Estado activo de la nav móvil */
    .mobile-nav-item.active span {
        color: var(--color-primary);
    }

    .mobile-nav-item.active .mobile-nav-icon {
        filter: brightness(0) invert(1) sepia(1) saturate(10) hue-rotate(10deg);
    }

    .mobile-nav-item.active svg.mobile-nav-icon {
        filter: none;
        color: var(--color-primary);
    }
}

/* =========================================
   RESPONSIVE - MÓVIL PEQUEÑO (≤ 400px)
   ========================================= */
@media (max-width: 400px) {
    .main-content {
        padding: 12px;
        padding-bottom: 85px;
        gap: 12px;
    }

    .header-left h1 {
        font-size: 20px;
    }

    .stat-value {
        font-size: 20px;
    }

    .chart-body {
        min-height: 140px;
        max-height: 180px;
    }

    .mobile-nav {
        height: 65px;
    }

    .mobile-nav-item span {
        font-size: 9px;
    }

    .mobile-nav-icon {
        width: 20px;
        height: 20px;
    }
}

