args.ReplacementContent:
    /* Sidebar */
    --sidebar-width: 260px;

    /* Bordes */
    --radius-sm: 8px;
    --radius-md: 12px;
    --radius-lg: 16px;
    --radius-pill: 50px;
}

body {
    font-family: var(--font-main);
    background-color: var(--color-bg-dark);
    color: var(--color-text-white);
    overflow-x: hidden;
}

/* =========================================
   APP SHELL (contenedor general)
   ========================================= */
.app-shell {
    display: flex;
    width: 100%;
    min-height: 100vh;
    background-color: var(--color-bg-dark);
    position: relative;
}

/* =========================================
   SIDEBAR
   ========================================= */
.sidebar {
    position: sticky;
    top: 0;
    flex-shrink: 0;
    width: var(--sidebar-width);
    height: 100vh;
    background-color: var(--color-bg-sidebar);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: 30px;
    z-index: 100;
}

/* =========================================
   LOGO
   ========================================= */
.sidebar .logo {
    display: flex;
    flex-direction: row;
    align-items: center;
    margin-bottom: 40px;
    gap: 12px;
}

.sidebar .logo .hexagon {
    width: 64px;
    min-width: 64px;
    height: 64px;
    background-color: var(--color-primary);
    clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
    display: flex;
    justify-content: center;
    align-items: center;
}

.sidebar .logo img {
    width: 44px;
    height: auto;
    object-fit: contain;
}

.sidebar .logo-text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    transform: translateY(-4px);
}

.sidebar .logo-text h1 {
    font-family: var(--font-main);
    color: var(--color-primary);
    font-size: 24px;
    font-weight: bold;
    margin: 0;
    line-height: 1;
}

.sidebar .logo-text p {
    font-family: var(--font-main);
    color: var(--color-text-gray);
    font-size: 14px;
    margin: 0;
    margin-top: 2px;
    white-space: nowrap;
}

/* =========================================
   MENÚ DE NAVEGACIÓN
   ========================================= */
.sidebar .menu {
    width: 100%;
}

.sidebar .menu ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar .menu ul li {
    width: 100%;
}

.sidebar .menu ul li a {
    font-family: var(--font-main);
    font-size: 16px;
    display: flex;
    align-items: center;
    gap: 16px;
    width: auto;
    padding: 12px 30px;
    color: var(--color-text-white);
    text-decoration: none;
    transition: all 0.2s ease;
}

.sidebar .menu ul li a .menu-icon {
    width: 22px;
    height: 22px;
    filter: brightness(0) invert(1);
    transition: filter 0.2s ease;
}

/* Estado hover del menú */
.sidebar .menu ul li a:hover {
    background-color: var(--color-primary);
    color: var(--color-text-dark);
    border: none;
    outline: none;
    border-radius: var(--radius-md);
}

.sidebar .menu ul li a:hover .menu-icon {
    filter: brightness(0);
}

/* Estado activo del menú (página actual) */
.sidebar .menu ul li a.active {
    background-color: var(--color-primary);
    color: var(--color-text-dark);
    border-radius: var(--radius-md);
    font-weight: 600;
}

.sidebar .menu ul li a.active .menu-icon {
    filter: brightness(0);
}

/* =========================================
   PERFIL DE USUARIO EN SIDEBAR
   ========================================= */
.sidebar .user-profile {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 16px;
    padding: 30px;
    margin-top: auto;
    margin-bottom: 20px;
    width: 100%;
    box-sizing: border-box;
}

.sidebar .user-avatar-indicator {
    position: relative;
    flex-shrink: 0;
}

.sidebar .user-profile .avatar-photo {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    object-fit: cover;
    display: none; /* Oculta por defecto hasta que cargue */
}

/* Cuando la foto carga exitosamente, JS le agrega .loaded */
.sidebar .user-profile .avatar-photo.loaded {
    display: block;
}

/* Ocultar iniciales cuando la foto está cargada */
.sidebar .user-profile .avatar-photo.loaded + .avatar-initials {
    display: none;
}

.sidebar .user-profile .avatar-initials {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    background-color: var(--color-primary);
    color: var(--color-text-dark);
    font-family: var(--font-main);
    font-size: 18px;
    font-weight: 700;
    display: flex;
    justify-content: center;
    align-items: center;
    letter-spacing: 1px;
}

.sidebar .status-dot {
    position: absolute;
    bottom: 2px;
    left: 0;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 2px solid var(--color-bg-sidebar);
}

.sidebar .status-dot.online {
    background-color: var(--color-alert-green);
}

.sidebar .user-profile .profile-text {
    display: flex;
    flex-direction: column;
}

.sidebar .user-profile h2 {
    font-family: var(--font-main);
    color: var(--color-text-white);
    font-size: 16px;
    font-weight: bold;
    margin: 0;
    line-height: 1.2;
}

.sidebar .user-profile p {
    font-family: var(--font-main);
    color: var(--color-text-gray);
    font-size: 14px;
    margin: 0;
}

