import json
import os

transcript_path = '/home/emma/.gemini/antigravity-cli/brain/e5402357-6f60-42c9-84f7-95b0c9b34173/.system_generated/logs/transcript.jsonl'
output_path = '/home/emma/SAM/HISTORIAL_CHAT.md'

with open(output_path, 'w', encoding='utf-8') as f:
    f.write("# Historial Completo del Chat con la IA\n\n")

    if os.path.exists(transcript_path):
        with open(transcript_path, 'r', encoding='utf-8') as infile:
            for line in infile:
                try:
                    data = json.loads(line)
                    if data.get('type') == 'USER_INPUT':
                        content = data.get('content', '')
                        # Clean up <USER_REQUEST> tags if they exist
                        content = content.replace('<USER_REQUEST>', '').replace('</USER_REQUEST>', '').strip()
                        f.write(f"### 👤 Usuario\n**Fecha:** {data.get('created_at', '')}\n\n{content}\n\n---\n\n")
                    elif data.get('type') == 'PLANNER_RESPONSE':
                        content = data.get('content', '')
                        if content.strip():
                            f.write(f"### 🤖 IA (Antigravity)\n**Fecha:** {data.get('created_at', '')}\n\n{content}\n\n---\n\n")
                except Exception as e:
                    pass
        print("Historial exportado correctamente.")
    else:
        print("No se encontro el archivo de historial.")
